(1, 'Gofran Muttaqi Likhan', 'internal', 'Mahasiswa Informatika & IoT/AI Developer', 'ITB PalComTech', 'gofranmuttaqi@gmail.com', '+6285669548964', '/gofran-profile.png', 'https://palcomtech.ac.id/', '{\"gpa\": \"3.95\", \"major\": \"Informatika\", \"domains\": [\"Administrasi & pelaporan\", \"Penjualan & layanan pelanggan\", \"Jaringan komputer\", \"IoT & AI\"], \"max_gpa\": \"4.00\", \"headline\": \"Halo Semua, Saya Gofran Muttaqi Likhan\", \"location\": \"Palembang, Indonesia\", \"semester\": 5, \"highlights\": [{\"title\": \"Technical Support\", \"caption\": \"Network · Hardware · Software\"}, {\"title\": \"Networking\", \"caption\": \"MikroTik · Cisco · Infrastruktur\"}, {\"title\": \"Administrasi\", \"caption\": \"Excel · Data · Pelaporan\"}, {\"title\": \"Operasional\", \"caption\": \"Koordinasi · Maintenance\"}, {\"title\": \"Teknologi\", \"caption\": \"IoT · AI · Python\"}], \"about_title\": \"Lintas bidang, satu cara berpikir: amati, catat, perbaiki.\", \"institution\": \"Institut Teknologi dan Bisnis PalComTech, Palembang\", \"subheadline\": \"Mahasiswa Informatika dengan latar belakang lintas bidang: administrasi, penjualan, layanan pelanggan, dan dukungan jaringan. Saat ini fokus membangun proyek berbasis IoT dan AI untuk menjawab masalah nyata di sekitar.\", \"status_badge\": \"Tersedia untuk bekerjasama\", \"contact_channels\": [{\"href\": \"https://wa.me/6285669548964?text=Halo%21%20saya%20ingin%20bekerja%20sama%20dengan%20anda\", \"icon\": \"whatsapp\", \"label\": \"WhatsApp\", \"primary\": true}, {\"href\": \"mailto:gofranmuttaqi@gmail.com?subject=Peluang%20Bekerjasama%20%2F%20Kolaborasi&body=Halo%20Gofran%2C%0A%0ASaya%20ingin%20membahas%20peluang%20bekerjasama%20atau%20kolaborasi%20dengan%20Anda.%0A%0ATerima%20kasih.\", \"icon\": \"email\", \"label\": \"Email\", \"primary\": false}, {\"href\": \"https://www.linkedin.com/in/gofran-ml\", \"icon\": \"linkedin\", \"label\": \"LinkedIn\", \"primary\": false}], \"about_description\": \"Saya mahasiswa Informatika dengan pengalaman lintas bidang — administrasi, pengolahan data, operasional, penjualan, serta pelayanan pelanggan. Terbiasa bekerja secara individu maupun dalam tim, dan belakangan aktif mengeksplorasi teknologi AI dan IoT untuk menyelesaikan masalah yang saya temui langsung di lapangan, mulai dari kualitas udara di transportasi umum hingga proses penjualan kendaraan.\"}', '2026-10-19 18:43:35', '2026-10-20 19:45:12'),
(2, 'PT. Bangka Cakra Karya', 'organization', 'Perusahaan Rental Alat Berat & Konstruksi', 'PT. Bangka Cakra Karya, Palembang', NULL, NULL, NULL, NULL, NULL, '2026-10-19 18:43:35', '2026-10-19 18:43:35'),
(3, 'Toyota Tunas Auto Graha', 'organization', 'Dealer Resmi Toyota', 'Toyota Tunas Auto Graha, Palembang', NULL, NULL, NULL, 'https://toyotatag.com', NULL, '2026-10-19 18:43:35', '2026-10-19 18:43:35'),
(4, 'Kedai Kopi Umak', 'organization', 'F&B Enterprise', 'Kedai Kopi Umak, Palembang', NULL, NULL, NULL, NULL, NULL, '2026-10-19 18:43:35', '2026-10-19 18:43:35'),
