-- Table structure for `events`
-- --------------------------------------------------------
DROP TABLE IF EXISTS `events`;
CREATE TABLE `events` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `agent_id` bigint unsigned DEFAULT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `organization` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `role_title` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `period` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `start_date` date DEFAULT NULL,
  `end_date` date DEFAULT NULL,
  `is_current` tinyint(1) NOT NULL DEFAULT '0',
  `summary` text COLLATE utf8mb4_unicode_ci,
  `details` json DEFAULT NULL,
  `metadata` json DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `events_agent_id_foreign` (`agent_id`),
  CONSTRAINT `events_agent_id_foreign` FOREIGN KEY (`agent_id`) REFERENCES `agents` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Dumping data for table `events`
INSERT INTO `events` (`id`, `agent_id`, `title`, `type`, `organization`, `role_title`, `period`, `start_date`, `end_date`, `is_current`, `summary`, `details`, `metadata`, `created_at`, `updated_at`) VALUES
(1, 2, 'Staf Umum', 'work_experience', 'PT. Bangka Cakra Karya, Palembang', 'Staf Umum', 'Jan – Mei 2026', NULL, NULL, 1, 'Mengelola operasional dan administrasi perusahaan sewa alat berat.', '[\"Mengelola administrasi operasional, termasuk pencatatan pemasukan dari penyewaan alat berat\", \"Menyusun laporan harian, mingguan, dan bulanan\", \"Mengelola lebih dari 10 transaksi penjualan dan pembelian suku cadang alat berat\", \"Mengoordinasikan operator dan sopir di lapangan\", \"Mengelola administrasi kepegawaian, absensi, dan perhitungan upah\", \"Memasang 10 unit CCTV di lingkungan kantor\"]', NULL, '2026-10-19 18:43:35', '2026-10-19 18:43:35'),
(2, 3, 'Sales Konsultan', 'work_experience', 'Toyota Tunas Auto Graha, Palembang', 'Sales Konsultan', 'Okt – Des 2025', NULL, NULL, 0, 'Konsultasi penjualan unit kendaraan roda empat dan pengelolaan relasi pelanggan.', '[\"Mengelola database prospek minimal 10 nomor per hari lewat canvassing, relasi, dan iklan Facebook\", \"Follow-up minimal 5 konsumen per hari & promosi produk di media sosial\", \"Mendampingi pelanggan dalam kegiatan unit test drive\"]', NULL, '2026-10-19 18:43:35', '2026-10-19 18:43:35'),
(3, 4, 'Barista & Kasir', 'work_experience', 'Kedai Kopi Umak, Palembang', 'Barista & Kasir', 'Mar – Nov 2025', NULL, NULL, 0, 'Pelayanan pelanggan dan transaksi kasir.', '[\"Menyiapkan dan menyajikan minuman sesuai standar kedai\", \"Melayani pelanggan dengan ramah, sopan, dan profesional\", \"Memproses transaksi pembayaran tunai maupun non-tunai\"]', NULL, '2026-10-19 18:43:35', '2026-10-19 18:43:35'),
(4, 5, 'Sales Konsultan', 'work_experience', 'Honda Maju Motor Group, Palembang', 'Sales Konsultan', 'Feb – Okt 2025', NULL, NULL, 0, 'Konsultan penjualan dan pelayanan pelanggan otomotif.', '[\"Mengelola database prospek & mendapatkan lead lewat canvassing dan pameran mobil\", \"Follow-up konsumen dan pendampingan unit test drive\", \"Memberikan informasi produk dan pelayanan secara profesional\"]', NULL, '2026-10-19 18:43:35', '2026-10-19 18:43:35'),
(5, 6, 'Staf Helper — Jaringan Komputer', 'work_experience', 'Sekretariat Daerah Kota Palembang', 'Staf Helper — Jaringan Komputer', 'Jan – Apr 2021', NULL, NULL, 0, 'Instalasi dan pemeliharaan infrastruktur jaringan instansi pemerintahan.', '[\"Instalasi & konfigurasi jaringan komputer di Ruang Pengadaan Barang dan Jasa\", \"Mengelola infrastruktur jaringan: 20+ komputer klien, router, switch, access point\", \"Konfigurasi dan troubleshooting perangkat MikroTik dan Cisco\", \"Monitoring rutin jaringan & server untuk menjaga uptime\"]', NULL, '2026-10-19 18:43:35', '2026-10-19 18:43:35');

