INSERT INTO `resources` (`id`, `title`, `slug`, `type`, `category`, `year`, `description`, `points`, `stack`, `image_url`, `external_url`, `is_featured`, `sort_order`, `metadata`, `created_at`, `updated_at`) VALUES
(1, 'Hyper-Local Air Quality Mapping via Public Transport-Based Sensing', 'hyper-local-air-quality-mapping', 'project', 'IoT & Artificial Intelligence', 'Proyek Mahasiswa · 2026', 'Riset dan pengembangan sistem pemantauan kualitas udara hyper-lokal dengan menempatkan perangkat sensor pada kendaraan umum. Sistem menggabungkan sensor, akuisisi data, pelacakan lokasi, serta pengolahan data untuk memetakan kondisi udara di sepanjang rute yang dilalui, lalu divisualisasikan sebagai heatmap secara real-time.', '[\"Sensor partikulat & gas: PMS5003, SDS011, ZH03B, MQ-135\", \"Pelacakan lokasi real-time dengan GPS Neo-6M\", \"Visualisasi heatmap via Google Maps API\", \"Interpolasi geospasial & filtering spatiotemporal\", \"Prediksi dengan Fuzzy Tsukamoto dan KNN\", \"Model KNN diekspor dengan joblib untuk inferensi\"]', '[\"ESP32\", \"BME280\", \"INA219\", \"Firebase\", \"Streamlit\", \"Plotly\", \"Laravel\", \"MySQL\", \"PHP\", \"XAMPP\"]', '/project-air-quality.png', NULL, 1, 1, '{\"gallery\": [{\"id\": \"admin-dashboard\", \"tag\": \"Command Center // Super Admin\", \"image\": \"/images/pollutrack/dashbord_admin_pollutrack.jpg\", \"title\": \"Dashboard Admin PolluTrack (Command Center)\", \"description\": \"Command center pemantauan telemetri sensor partikulat (PM2.5, PM10, PM1), gas MQ135, kelembapan udara, tekanan atmosfer, dan deteksi hujan secara real-time disertai manajemen node cluster dan status kesehatan perangkat IoT.\", \"short_title\": \"Dashboard Admin\"}, {\"id\": \"public-dashboard\", \"tag\": \"Public Portal // Live Heatmap\", \"image\": \"/images/pollutrack/dashbord_publik_pollutrack.jpg\", \"title\": \"Dashboard Publik PolluTrack (Public Live Portal)\", \"description\": \"Portal publik interaktif yang menampilkan kondisi kualitas udara kota secara langsung, indikator AQI untuk kelompok rentan, status stasiun pemantau aktif, serta integrasi peta spasial rute transportasi umum.\", \"short_title\": \"Dashboard Publik\"}, {\"id\": \"admin-login\", \"tag\": \"Autentikasi & Kontrol Akses\", \"image\": \"/images/pollutrack/login_admin_pollutrack.jpg\", \"title\": \"Halaman Login Admin PolluTrack\", \"description\": \"Antarmuka autentikasi berkeamanan tinggi bagi administrator, operator, dan teknisi lapangan sebelum mengakses konfigurasi sistem IoT, manajemen user, dan data telemetri historis.\", \"short_title\": \"Login Admin\"}]}', '2026-10-19 18:43:35', '2026-10-20 19:45:12'),
(2, 'Website Penjualan Toyota dengan AI Chatbot', 'website-penjualan-toyota-ai-chatbot', 'project', 'Web Development & AI Integration', 'Proyek Mahasiswa · 2026', 'Website bertema penjualan kendaraan Toyota sebagai eksplorasi web development dan integrasi AI, dengan chatbot yang berperan sebagai virtual salesman untuk membantu interaksi dan kebutuhan informasi calon pembeli.', '[\"AI chatbot sebagai virtual salesman\", \"Kalkulator simulasi kredit kendaraan\", \"Tampilan visual 3D & fitur 360° interior/eksterior\", \"Halaman model kendaraan & profil sales\", \"Dashboard administrasi\", \"URL shortener & tracking, dynamic branding\"]', '[\"Web Development\", \"Artificial Intelligence\", \"AI Chatbot\", \"3D Visualization\", \"Admin Dashboard\"]', '/project-toyota.png', NULL, 1, 2, NULL, '2026-10-19 18:43:35', '2026-10-19 18:43:35'),
